use std::error::Error;

use crate::domain::{ClassificationKind, Remediation};

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SupportMatrix;

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SupportMatrixEntry {
    pub capability: String,
    pub classification: ClassificationKind,
    pub remediation: Remediation,
}

pub trait SupportMatrixReader {
    type Error: Error + Send + Sync + 'static;

    /// Retrieves the capability classifications generated by supported adapters.
    ///
    /// # Errors
    ///
    /// Returns the adapter-specific error when matrix retrieval fails.
    fn read(&self) -> Result<Vec<SupportMatrixEntry>, Self::Error>;
}

/// Reads the tested conversion capability matrix.
///
/// # Errors
///
/// Propagates the adapter error returned by [`SupportMatrixReader`].
pub fn handle<Reader>(reader: &Reader) -> Result<Vec<SupportMatrixEntry>, Reader::Error>
where
    Reader: SupportMatrixReader,
{
    reader.read()
}
